void backend_tir_tmod_report(struct backend_tir_TModule * self, const char * unit, double ms) {
    const char * e;
    int i;
    int td;
    int ti;
    int tv;
    int tx;
    int tr;
    int tc;
    int tb;
    int tvar;
    int tun;
    e = getenv("CT_TIR_REPORT");
    if (((!e) || (!e[0]))) {
        return;
    }
    td = 0;
    ti = 0;
    tv = 0;
    tx = 0;
    tr = 0;
    tc = 0;
    tb = 0;
    tvar = 0;
    tun = 0;
    for (i = 0; i < self->nexprs; i++) {
        switch (self->exprs[i].target_kind) {
            case RT_DIRECT:
                td++;
                break;
            case RT_INDIRECT:
                ti++;
                break;
            case RT_VIRTUAL:
                tv++;
                break;
            case RT_INTRINSIC:
                tx++;
                break;
            case RT_RECIPE:
                tr++;
                break;
            case RT_CLOSURE:
                tc++;
                break;
            case RT_BUILTIN:
                tb++;
                break;
            case RT_VAR:
                tvar++;
                break;
            case RT_NONE:
                tun++;
                break;
        }
    }
    self->stat_ms += ms;
    self->stat_units_seen += 1;
    self->stat_exprs_seen += self->nexprs;
    fprintf(stderr, "tir: unit=%s units=%d decls=%d types=%d exprs=%d stmts=%d scopes=%d"" vars=%d cleanups=%d insts=%d members=%d roots=%d graph=%d/%d"" targets=d%d/i%d/v%d/x%d/r%d/c%d/b%d/var%d none=%d"" fallback_types=%d raw_opaque=%d unresolved=%d time_ms=%.3f\n", (unit ? unit : ""), self->nunits, self->ndecls, self->ntypes, self->nexprs, self->nstmts, self->nscopes, self->nvars, self->ncleanups, self->ninsts, self->nmembers, self->nroots, self->graph.nnodes, self->graph.nedges, td, ti, tv, tx, tr, tc, tb, tvar, tun, self->stat_fallback_type, self->stat_raw_expr, self->stat_unknown_target, ms);
}
